<template><view class="slide" :class="{disabled}" @touchstart="start" @touchmove="move" @touchend="end"><view class="thumb" :style="{transform:`translateX(${offset}px)`}">›</view><text>{{label}}</text></view></template>
<script setup lang="ts">import{ref}from'vue';const props=defineProps<{label:string;disabled?:boolean}>();const emit=defineEmits<{confirm:[]}>();const offset=ref(0);let x=0;function start(e:any){x=Number(e.touches?.[0]?.clientX||0)}function move(e:any){if(props.disabled)return;offset.value=Math.max(0,Math.min(240,Number(e.touches?.[0]?.clientX||0)-x))}function end(){if(offset.value>190&&!props.disabled)emit('confirm');offset.value=0}</script>
<style scoped>.slide{height:92rpx;border-radius:46rpx;background:#e2e8f0;display:flex;align-items:center;justify-content:center;position:relative;color:#475569;font-weight:600}.slide.disabled{opacity:.5}.thumb{position:absolute;left:8rpx;width:76rpx;height:76rpx;border-radius:50%;background:#0f172a;color:#fff;display:grid;place-items:center;font-size:48rpx;transition:transform .18s}</style>
